#pragma once
#include "DeviceReader.h"
#include <map>
namespace hub {
// Generic, passive HID input reader. Byte positions and model matching remain in plugin metadata.
struct PluginInputReader {
 HANDLE handle=INVALID_HANDLE_VALUE,event{};OVERLAPPED ov{};bool pending=false;std::vector<unsigned char> buffer,last;ULONGLONG sampled{},attempted{};JsonObject rule;std::wstring error;
 explicit PluginInputReader(JsonObject value):rule(value){}
 ~PluginInputReader(){close();}
 void close(){if(handle!=INVALID_HANDLE_VALUE){CancelIoEx(handle,&ov);if(pending)WaitForSingleObject(event,1000);CloseHandle(handle);handle=INVALID_HANDLE_VALUE;}if(event){CloseHandle(event);event=nullptr;}pending=false;last.clear();sampled=0;}
 void connect(){attempted=GetTickCount64();GUID hid{};HidD_GetHidGuid(&hid);auto set=SetupDiGetClassDevsW(&hid,nullptr,nullptr,DIGCF_PRESENT|DIGCF_DEVICEINTERFACE);if(set==INVALID_HANDLE_VALUE)return;std::wstring path;unsigned length=0;
  for(DWORD i=0;;i++){SP_DEVICE_INTERFACE_DATA item{sizeof(item)};if(!SetupDiEnumDeviceInterfaces(set,nullptr,&hid,i,&item))break;DWORD bytes{};SetupDiGetDeviceInterfaceDetailW(set,&item,nullptr,0,&bytes,nullptr);if(bytes<sizeof(SP_DEVICE_INTERFACE_DETAIL_DATA_W)||bytes>65536)continue;std::vector<unsigned char> storage(bytes);auto detail=(SP_DEVICE_INTERFACE_DETAIL_DATA_W*)storage.data();detail->cbSize=sizeof(*detail);if(!SetupDiGetDeviceInterfaceDetailW(set,&item,detail,bytes,nullptr,nullptr))continue;HANDLE h=CreateFileW(detail->DevicePath,0,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,0,nullptr);if(h==INVALID_HANDLE_VALUE)continue;HIDD_ATTRIBUTES attributes{sizeof(attributes)};PHIDP_PREPARSED_DATA prep{};
   if(HidD_GetAttributes(h,&attributes)&&attributes.VendorID==num(rule,L"vid")&&attributes.ProductID==num(rule,L"pid")&&HidD_GetPreparsedData(h,&prep)){HIDP_CAPS caps{};if(HidP_GetCaps(prep,&caps)==HIDP_STATUS_SUCCESS&&caps.UsagePage==num(rule,L"usagePage")&&caps.Usage==num(rule,L"inputUsage")&&caps.InputReportByteLength>1&&caps.InputReportByteLength<=4097){if(!path.empty()){HidD_FreePreparsedData(prep);CloseHandle(h);SetupDiDestroyDeviceInfoList(set);error=L"存在多个状态接口，拒绝混合电量";return;}path=detail->DevicePath;length=caps.InputReportByteLength;}HidD_FreePreparsedData(prep);}CloseHandle(h);
  }SetupDiDestroyDeviceInfoList(set);if(path.empty()){error=L"未找到电量状态接口";return;}handle=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr);if(handle==INVALID_HANDLE_VALUE){error=L"电量状态接口无法打开";return;}event=CreateEventW(nullptr,TRUE,FALSE,nullptr);buffer.resize(length);error.clear();
 }
 static JsonObject decode(JsonObject rule,std::vector<unsigned char> const& bytes){JsonObject result;auto rid=num(rule,L"reportId",-1);auto maskOffset=(unsigned)num(rule,L"signatureOffset",1),offset=(unsigned)num(rule,L"batteryOffset",4097);if(bytes.empty()||bytes[0]!=rid||maskOffset>=bytes.size()||offset>=bytes.size())return result;auto mask=(unsigned)num(rule,L"signatureMask",255),expected=(unsigned)num(rule,L"signatureValue",0);if((bytes[maskOffset]&mask)!=expected||bytes[offset]>100)return result;put(result,L"battery",(double)bytes[offset]);put(result,L"lowBattery",bytes[offset]<=num(rule,L"lowBatteryThreshold",15));auto status=(unsigned)num(rule,L"statusOffset",4097);if(status<bytes.size())put(result,L"batteryStatusRaw",(double)bytes[status]);auto connectedOffset=(unsigned)num(rule,L"connectedOffset",4097);if(connectedOffset<bytes.size())put(result,L"connected",(bytes[connectedOffset]&(unsigned)num(rule,L"connectedMask",128))!=0);return result;}
 void tick(){if(handle==INVALID_HANDLE_VALUE){if(GetTickCount64()-attempted>3000)connect();if(handle==INVALID_HANDLE_VALUE)return;}DWORD got{};
  if(pending){if(WaitForSingleObject(event,0)!=WAIT_OBJECT_0)return;if(!GetOverlappedResult(handle,&ov,&got,FALSE)){error=L"状态接口断开";close();return;}pending=false;accept(got);}
  ResetEvent(event);ov={};ov.hEvent=event;BOOL ok=ReadFile(handle,buffer.data(),(DWORD)buffer.size(),&got,&ov);if(ok){accept(got);}else if(GetLastError()==ERROR_IO_PENDING)pending=true;else{error=L"状态上报读取失败";close();}
 }
 void accept(DWORD count){std::vector<unsigned char> bytes(buffer.begin(),buffer.begin()+std::min<size_t>(count,buffer.size()));if(decode(rule,bytes).HasKey(L"battery")){last=std::move(bytes);sampled=GetTickCount64();error.clear();}}
 JsonObject snapshot(){auto result=decode(rule,last);if(!sampled||GetTickCount64()-sampled>60000)result=JsonObject{};put(result,L"ok",true);if(result.HasKey(L"connected")&&!flag(result,L"connected")){result.Remove(L"battery");result.Remove(L"lowBattery");}put(result,L"available",result.HasKey(L"battery"));if(sampled)put(result,L"ageSeconds",(double)(GetTickCount64()-sampled)/1000);put(result,L"source",std::wstring(L"插件 HID 状态上报"));if(!error.empty())put(result,L"error",error);std::wstring raw;for(auto byte:last){wchar_t b[4]{};swprintf_s(b,L"%02X ",byte);raw+=b;}put(result,L"rawReport",raw);return result;}
};
struct PluginTelemetry {
 std::map<std::wstring,std::unique_ptr<PluginInputReader>> readers;std::wstring signature;
 void sync(JsonObject state){std::wstring next;std::map<std::wstring,JsonObject> rules;for(auto const& value:state.GetNamedArray(L"plugins")){auto p=value.GetObject();if(!flag(p,L"installed")||flag(p,L"forceStopped")||str(p,L"mode")==L"disabled"||!p.HasKey(L"inputTelemetry"))continue;bool granted=false;for(auto const& permission:p.GetNamedArray(L"permissions",JsonArray{}))if(permission.GetString()==L"USB HID 配置")granted=true;if(!granted)continue;auto rule=p.GetNamedObject(L"inputTelemetry");bool matched=false;for(auto const& target:p.GetNamedArray(L"hidTargets",JsonArray{})){auto t=target.GetObject();if(num(rule,L"vid")==num(t,L"vid")&&num(rule,L"pid")==num(t,L"pid")&&num(rule,L"usagePage")==num(t,L"usagePage"))matched=true;}if(!matched)continue;auto id=str(p,L"id");rules[id]=rule;next+=id+std::wstring(rule.Stringify());}
  if(next!=signature){readers.clear();for(auto const& [id,rule]:rules)readers[id]=std::make_unique<PluginInputReader>(rule);signature=next;}for(auto const& [id,reader]:readers)reader->tick();
 }
 JsonObject snapshot(std::wstring id){auto i=readers.find(id);if(i==readers.end())throw hresult_error(E_ACCESSDENIED,L"插件未启用电量读取");return i->second->snapshot();}
 void decorate(JsonObject detected){for(auto key:{L"devices",L"peripherals"})for(auto const& value:detected.GetNamedArray(key,JsonArray{})){auto d=value.GetObject();if(str(d,L"batterySource")==L"插件 HID 状态上报"){for(auto field:{L"battery",L"lowBattery",L"batteryAgeSeconds",L"batterySource"})if(d.HasKey(field))d.Remove(field);put(d,L"status",std::wstring(L"接口存在 · 等待无线状态上报"));}for(auto const& [id,reader]:readers){if(num(d,L"vid",-1)!=num(reader->rule,L"vid")||num(d,L"pid",-1)!=num(reader->rule,L"pid"))continue;auto s=reader->snapshot();if(!flag(s,L"available"))continue;d.SetNamedValue(L"battery",s.GetNamedValue(L"battery"));d.SetNamedValue(L"lowBattery",s.GetNamedValue(L"lowBattery"));put(d,L"batterySource",str(s,L"source"));put(d,L"batteryAgeSeconds",num(s,L"ageSeconds"));if(s.HasKey(L"connected"))put(d,L"connected",flag(s,L"connected"));put(d,L"status",std::wstring(L"已连接 · 鼠标状态上报"));}}
 }
};
inline int pluginInputProbe(std::filesystem::path input,std::filesystem::path output){auto rule=object(read(input));PluginInputReader reader(rule);auto deadline=GetTickCount64()+10000;while(GetTickCount64()<deadline){reader.tick();if(!reader.last.empty())break;Sleep(20);}auto result=reader.snapshot();write(output,std::wstring(result.Stringify()));return flag(result,L"available")?0:1;}
}
